import 'dart:async';
import 'dart:math';
import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:audioplayers/audioplayers.dart';

// === البداية - الربط مع جوجل ===
void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(); // Google Firebase
  runApp(const AuraApp());
}

class AuraApp extends StatelessWidget {
  const AuraApp({super.key});
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'AURA ARMY GOOGLE',
      theme: ThemeData.dark(),
      home: const AuraArmyGoogleV18(),
    );
  }
}

// تعريف بنية جزيئات الجيش الوفي
class ArmyDot {
  double x;
  double y;
  final Color color;
  final String ownerId;

  ArmyDot({required this.x, required this.y, required this.color, required this.ownerId});
}

// تعريف بنية القلوب المتطايرة (Like Burst)
class BurstHeart {
  double x;
  double y;
  double velocityX;
  double velocityY;
  double opacity;
  final Color color;

  BurstHeart({
    required this.x,
    required this.y,
    required this.velocityX,
    required this.velocityY,
    required this.opacity,
    required this.color,
  });
}

class AuraArmyGoogleV18 extends StatefulWidget {
  const AuraArmyGoogleV18({super.key});
  @override
  State<AuraArmyGoogleV18> createState() => _AuraArmyGoogleV18State();
}

class _AuraArmyGoogleV18State extends State<AuraArmyGoogleV18> with TickerProviderStateMixin {
  List<ArmyDot> army = [];
  List<BurstHeart> burstHearts = []; 
  List<String> liveChatMessages = []; 

  Offset target = const Offset(200, 400);
  late AnimationController controller;
  final Random rand = Random();
  final AudioPlayer audio = AudioPlayer();

  final TextEditingController cmdController = TextEditingController();
  final TextEditingController borrowController = TextEditingController();
  final ScrollController _chatScrollController = ScrollController(); 

  // === المفتاح السري والمحدد لمالك المشروع ===
  String myId = "064313lh"; 
  String status = "مرتبط بجوجل Firebase - الجيش وفي ليك بوحدك 👑";
  bool isLent = false;
  Timer? lendTimer;
  String currentLendCode = "";

  @override
  void initState() {
    super.initState();

    // محرك الحركة الرئيسي (60 إطار في الثانية)
    controller = AnimationController(vsync: this, duration: const Duration(seconds: 10))..repeat();
    controller.addListener(() {
      // 1. جذب ذرات الجيش نحو الهدف الملكي (الإصبع)
      for (var d in army) {
        d.x += (target.dx - d.x) * 0.02 + (rand.nextDouble() - 0.5);
        d.y += (target.dy - d.y) * 0.02 + (rand.nextDouble() - 0.5);
      }

      // 2. تحديث فيزيائية القلوب المتطايرة وتلاشيها
      for (int i = burstHearts.length - 1; i >= 0; i--) {
        var heart = burstHearts[i];
        heart.x += heart.velocityX;
        heart.y += heart.velocityY;
        heart.opacity -= 0.02; 
        if (heart.opacity <= 0) {
          burstHearts.removeAt(i);
        }
      }

      if (mounted) setState(() {});
    });

    // 3. الربط السحابي الحقيقي والاستماع المباشر للتفاعل من تيك توك عبر فايبربيز
    _initFirebaseTikTokStream();

    // إطلاق مبدئي للجيش بصوت صامت
    spawnArmy(200, withSound: false);
  }

  void _initFirebaseTikTokStream() {
    // مراقبة عداد المشاهدين الإجمالي لشحن كمية الجيش حياً
    FirebaseFirestore.instance
        .collection('aura_live_sessions')
        .doc('lmkhizeni2') 
        .snapshots()
        .listen((snapshot) {
      if (snapshot.exists && snapshot.data() != null) {
        var data = snapshot.data()!;
        int currentViewers = data['current_viewers'] ?? 0;
        if (currentViewers > 0) {
          _spawnRealArmyFromTikTok(currentViewers);
        }
      }
    });

    // مراقبة تعليقات بث تيك توك الحية المتدفقة وعرضها مع تمرير تلقائي (Auto-Scroll)
    FirebaseFirestore.instance
        .collection('aura_live_sessions')
        .doc('lmkhizeni2')
        .collection('live_chat')
        .orderBy('timestamp', descending: false)
        .snapshots()
        .listen((snapshot) {
      if (snapshot.docs.isNotEmpty) {
        setState(() {
          liveChatMessages = snapshot.docs.map((doc) => "${doc['username']}: ${doc['message']}").toList();
        });

        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (_chatScrollController.hasClients) {
            _chatScrollController.animateTo(
              _chatScrollController.position.maxScrollExtent,
              duration: const Duration(milliseconds: 300),
              curve: Curves.easeOut,
            );
          }
        });
      }
    });

    // الاستماع للهدايا والتفاعلات لتوليد إنفجار القلوب (Like Burst Effect)
    FirebaseFirestore.instance
        .collection('aura_live_sessions')
        .doc('lmkhizeni2')
        .collection('live_gifts')
        .snapshots()
        .listen((snapshot) {
      _triggerLikeBurstEffect();
    });
  }

  void _triggerLikeBurstEffect() {
    final List<Color> heartColors = [Colors.redAccent, Colors.pinkAccent, Colors.orangeAccent, Colors.purpleAccent];
    setState(() {
      for (int i = 0; i < 15; i++) {
        burstHearts.add(BurstHeart(
          x: target.dx,
          y: target.dy,
          velocityX: (rand.nextDouble() - 0.5) * 8, 
          velocityY: (rand.nextDouble() - 1.0) * 10, 
          opacity: 1.0,
          color: heartColors[rand.nextInt(heartColors.length)],
        ));
      }
    });
  }

  void _spawnRealArmyFromTikTok(int count) {
    if (isLent) return;
    int botCount = count > 1500 ? 1500 : count; // سقف الحماية لمنع بطء المعالج
    setState(() {
      army = List.generate(botCount, (_) => ArmyDot(
        x: rand.nextDouble() * 350,
        y: rand.nextDouble() * 700 + 100,
        color: const Color(0xFFD4AF37),
        ownerId: myId,
      ));
      status = "📡 جيش أورا وفي 100% - مستجيب لحسابك تيك توك الحقيقي ($count مشاهد)";
    });
  }

  void spawnArmy(int count, {bool withSound = true}) async {
    if (isLent) { setState(() => status = "⛔ الجيش مسلف دابا - ما تقدرش تطلقو حتى يرجع"); return; }

    if (withSound) {
      try {
        await audio.play(AssetSource('sounds/army_release.mp3'));
      } catch (_) {}
    }

    army = List.generate(count, (_) => ArmyDot(
      x: rand.nextDouble() * 300,
      y: rand.nextDouble() * 600 + 100,
      color: const Color(0xFFD4AF37),
      ownerId: myId,
    ));

    await FirebaseFirestore.instance.collection('aura_army_logs').add({
      'ownerId': myId,
      'count': count,
      'action': 'spawn',
      'createdAt': FieldValue.serverTimestamp(),
    });

    setState(() => status = "🔥 طلقتي $count مساعد - مربوطين بـ $myId - محفوظين فجوجل");
  }

  void executeCommand() {
    String command = cmdController.text.trim();
    if (command.isEmpty) return;
    if (command.toLowerCase() != myId.toLowerCase() && !command.toLowerCase().contains("lahcen") && command != "064313lh") {
      setState(() => status = "⛔ أمر مرفوض - الجيش كيسمع غير لـ $myId");
      return;
    }
    setState(() => status = "✅ أمر مقبول من الملك $myId - الجيش كيهجم!");
    spawnArmy(1000, withSound: true);
    cmdController.clear();
  }

  Future<void> lendToFriend() async {
    String lendCode = (100000 + rand.nextInt(900000)).toString();
    await FirebaseFirestore.instance.collection('aura_lends').doc(lendCode).set({
      'ownerId': myId,
      'code': lendCode,
      'createdAt': FieldValue.serverTimestamp(),
      'expiresAt': DateTime.now().add(const Duration(hours: 24)),
      'status': 'active',
    });
    setState(() { 
      isLent = true; 
      currentLendCode = lendCode;
      status = "📤 سلفتي الجيش بكود $lendCode - 24 ساعة ويرجع بوحدو - محفوظ فجوجل"; 
    });

    lendTimer?.cancel();
    lendTimer = Timer(const Duration(hours: 24), () async {
      await FirebaseFirestore.instance.collection('aura_lends').doc(lendCode).update({'status': 'returned'});
      if(mounted) setState(() { isLent = false; status = "👑 الجيش رجع لعندك من جوجل - الوفاء ديالو ليك بوحدك"; });
    });
  }

  Future<void> useBorrowedCode() async {
    String code = borrowController.text.trim();
    if(code.isEmpty) return;
    var doc = await FirebaseFirestore.instance.collection('aura_lends').doc(code).get();
    if (!doc.exists || doc.data()?['status'] != 'active') {
      setState(() => status = "⛔ كود غالط ولا سالا الوقت ديالو");
      return;
    }
    setState(() => status = "🤝 راك خدام بجيش ${doc.data()?['ownerId']} - مؤقت من جوجل");
    spawnArmy(500);
    borrowController.clear();
  }

  Future<void> returnArmyNow() async {
    if(currentLendCode.isNotEmpty){
      await FirebaseFirestore.instance.collection('aura_lends').doc(currentLendCode).update({'status': 'returned'});
    }
    lendTimer?.cancel();
    setState(() { isLent = false; status = "👑 رجعتي الجيش بيدك - راه عندك دابا"; });
  }

  @override
  void dispose() {
    controller.dispose();
    audio.dispose();
    cmdController.dispose();
    borrowController.dispose();
    _chatScrollController.dispose();
    lendTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      appBar: AppBar(
        backgroundColor: Colors.black,
        centerTitle: true,
        title: const Text('AURA ARMY V18 - LIVE REACTION', style: TextStyle(color: Color(0xFFD4AF37), fontSize: 13, fontWeight: FontWeight.bold)),
        actions: [IconButton(onPressed: returnArmyNow, icon: const Icon(Icons.undo, color: Colors.white54))],
      ),
      body: Stack(
        children: [
          GestureDetector(
            onPanUpdate: (d) => setState(() => target = d.localPosition),
            onTapDown: (d) => setState(() => target = d.localPosition),
