class AuraArmyGoogleV18 extends StatefulWidget {
  const AuraArmyGoogleV18({super.key});
  @override
  State<AuraArmyGoogleV18> createState() => _AuraArmyGoogleV18State();
}

class _AuraArmyGoogleV18State extends State<AuraArmyGoogleV18> with TickerProviderStateMixin {
  List<ArmyDot> _army = [];
  List<BurstHeart> _burstHearts = []; 
  List<String> _liveChatMessages = []; 

  Offset _target = const Offset(200, 400);
  late AnimationController _animationController;
  final Random _rand = Random();
  final AudioPlayer _audioPlayer = AudioPlayer();

  final TextEditingController _cmdController = TextEditingController();
  final TextEditingController _borrowController = TextEditingController();
  final ScrollController _chatScrollController = ScrollController(); 

  // 🔒 متغيرات خاصة لحماية الوفاء والمصادقة الأمنية لمالك المشروع
  final String _myId = "064313lh"; 
  String _status = "مرتبط بجوجل Firebase - الجيش وفي ليك بوحدك 👑";
  bool _isLent = false;
  Timer? _lendTimer;
  String _currentLendCode = "";

  @override
  void initState() {
    super.initState();

    // محرك الحركة الرئيسي (60 إطار في الثانية) مع تحسين الأداء
    _animationController = AnimationController(vsync: this, duration: const Duration(seconds: 10))..repeat();
    _animationController.addListener(() {
      if (!mounted) return;

      // 1. جذب ذرات الجيش نحو الهدف الملكي (الإصبع)
      for (var d in _army) {
        d.x += (_target.dx - d.x) * 0.02 + (_rand.nextDouble() - 0.5);
        d.y += (_target.dy - d.y) * 0.02 + (_rand.nextDouble() - 0.5);
      }

      // 2. تحديث فيزيائية وتلاشي القلوب المتطايرة
      for (int i = _burstHearts.length - 1; i >= 0; i--) {
        var heart = _burstHearts[i];
        heart.x += heart.velocityX;
        heart.y += heart.velocityY;
        heart.opacity -= 0.02; 
        if (heart.opacity <= 0) {
          _burstHearts.removeAt(i);
        }
      }

      setState(() {});
    });

    // الربط السحابي الحقيقي والاستماع للتفاعل الحي من تيك توك عبر فايبربيز
    _initFirebaseTikTokStream();

    // إطلاق مبدئي صامت للجيش الافتراضي
    _spawnArmyInternal(200, withSound: false);
  }

  void _initFirebaseTikTokStream() {
    // مراقبة عداد المشاهدين الإجمالي لشحن كمية الجيش حياً
    FirebaseFirestore.instance
        .collection('aura_live_sessions')
        .doc('lmkhizeni2') 
        .snapshots()
        .listen((snapshot) {
      if (!mounted || !snapshot.exists || snapshot.data() == null) return;
      var data = snapshot.data()!;
      int currentViewers = data['current_viewers'] ?? 0;
      if (currentViewers > 0) {
        _spawnRealArmyFromTikTok(currentViewers);
      }
    });

    // مراقبة تعليقات بث تيك توك الحية المتدفقة وعرضها مع تمرير تلقائي (Auto-Scroll)
    FirebaseFirestore.instance
        .collection('aura_live_sessions')
        .doc('lmkhizeni2')
        .collection('live_chat')
        .orderBy('timestamp', descending: false)
        .snapshots()
        .listen((snapshot) {
      if (!mounted || snapshot.docs.isEmpty) return;
      setState(() {
        _liveChatMessages = snapshot.docs.map((doc) => "${doc['username']}: ${doc['message']}").toList();
      });

      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (_chatScrollController.hasClients) {
          _chatScrollController.animateTo(
            _chatScrollController.position.maxScrollExtent,
            duration: const Duration(milliseconds: 300),
            curve: Curves.easeOut,
          );
        }
      });
    });

    // الاستماع للهدايا والتفاعلات لتوليد إنفجار القلوب (Like Burst Effect)
    FirebaseFirestore.instance
        .collection('aura_live_sessions')
        .doc('lmkhizeni2')
        .collection('live_gifts')
        .snapshots()
        .listen((snapshot) {
      if (!mounted) return;
      _triggerLikeBurstEffect();
    });
  }

  void _triggerLikeBurstEffect() {
    final List<Color> heartColors = [Colors.redAccent, Colors.pinkAccent, Colors.orangeAccent, Colors.purpleAccent];
    setState(() {
      for (int i = 0; i < 15; i++) {
        _burstHearts.add(BurstHeart(
          x: _target.dx,
          y: _target.dy,
          velocityX: (_rand.nextDouble() - 0.5) * 8, 
          velocityY: (_rand.nextDouble() - 1.0) * 10, 
          opacity: 1.0,
          color: heartColors[_rand.nextInt(heartColors.length)],
        ));
      }
    });
  }

  void _spawnRealArmyFromTikTok(int count) {
    if (_isLent) return;
    int botCount = count > 1500 ? 1500 : count; // سقف الحماية لمنع بطء المعالج
    setState(() {
      _army = List.generate(botCount, (_) => ArmyDot(
        x: _rand.nextDouble() * 350,
        y: _rand.nextDouble() * 700 + 100,
        color: const Color(0xFFD4AF37),
        ownerId: _myId,
      ));
      _status = "📡 جيش أورا وفي 100% - مستجيب لحسابك تيك توك الحقيقي ($count مشاهد)";
    });
  }

  void _spawnArmyInternal(int count, {required bool withSound}) async {
    if (_isLent) return;
    if (withSound) {
      try {
        await _audioPlayer.play(AssetSource('sounds/army_release.mp3'));
      } catch (_) {}
    }
    setState(() {
      _army = List.generate(count, (_) => ArmyDot(
        x: _rand.nextDouble() * 300,
        y: _rand.nextDouble() * 600 + 100,
        color: const Color(0xFFD4AF37),
        ownerId: _myId,
      ));
    });
  }

  void spawnArmyExternal(int count) async {
    if (_isLent) { setState(() => _status = "⛔ الجيش مسلف دابا - ما تقدرش تطلقو حتى يرجع"); return; }
    _spawnArmyInternal(count, withSound: true);

    await FirebaseFirestore.instance.collection('aura_army_logs').add({
      'ownerId': _myId,
      'count': count,
      'action': 'spawn',
      'createdAt': FieldValue.serverTimestamp(),
    });

    setState(() => _status = "🔥 طلقتي $count مساعد - مربوطين بـ $_myId - محفوظين فجوجل");
  }

  void executeCommand() {
    String command = _cmdController.text.trim();
    if (command.isEmpty) return;
    if (command.toLowerCase() != _myId.toLowerCase() && !command.toLowerCase().contains("lahcen") && command != "064313lh") {
      setState(() => _status = "⛔ أمر مرفوض - الجيش كيسمع غير لـ $_myId");
      return;
    }
    setState(() => _status = "✅ أمر مقبول من الملك $_myId - الجيش كيهجم!");
    spawnArmyExternal(1000);
    _cmdController.clear();
  }

  Future<void> lendToFriend() async {
    String lendCode = (100000 + _rand.nextInt(900000)).toString();
    await FirebaseFirestore.instance.collection('aura_lends').doc(lendCode).set({
      'ownerId': _myId,
      'code': lendCode,
      'createdAt': FieldValue.serverTimestamp(),
      'expiresAt': DateTime.now().add(const Duration(hours: 24)),
      'status': 'active',
    });
    setState(() { 
      _isLent = true; 
      _currentLendCode = lendCode;
      _status = "📤 سلفتي الجيش بكود $lendCode - 24 ساعة ويرجع بوحدو - محفوظ فجوجل"; 
    });

    _lendTimer?.cancel();
    _lendTimer = Timer(const Duration(hours: 24), () async {
      await FirebaseFirestore.instance.collection('aura_lends').doc(lendCode).update({'status': 'returned'});
      if (mounted) setState(() { _isLent = false; _status = "👑 الجيش رجع لعندك من جوجل - الوفاء ديالو ليك بوحدك"; });
    });
  }

  Future<void> useBorrowedCode() async {
    String code = _borrowController.text.trim();
    if (code.isEmpty) return;
    var doc = await FirebaseFirestore.instance.collection('aura_lends').doc(code).get();
    if (!doc.exists || doc.data()?['status'] != 'active') {
      setState(() => _status = "⛔ كود غالط ولا سالا الوقت ديالو");
      return;
    }
    setState(() => _status = "🤝 راك خدام بجيش ${doc.data()?['ownerId']} - مؤقت من جوجل");
    _spawnArmyInternal(500, withSound: true);
    _borrowController.clear();
  }

  Future<void> returnArmyNow() async {
    if (_currentLendCode.isNotEmpty) {
      await FirebaseFirestore.instance.collection('aura_lends').doc(_currentLendCode).update({'status': 'returned'});
    }
    _lendTimer?.cancel();
    setState(() { _isLent = false; _status = "👑 رجعتي الجيش بيدك - راه عندك دابا"; });
  }

  @override
  void dispose() {
    _animationController.dispose();
    _audioPlayer.dispose();
    _cmdController.dispose();
    _borrowController.dispose();
    _chatScrollController.dispose();
    _lendTimer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      appBar: AppBar(
        backgroundColor: Colors.black,
        centerTitle: true,
        title: const Text('AURA ARMY V18 - LIVE REACTION', style: TextStyle(color: Color(0xFFD4AF37), fontSize: 13, fontWeight: FontWeight.bold)),

