/// === الرسام المخصص (Custom Painter) لرسم الجيش والقلوب ===
class ArmyAndHeartPainter extends CustomPainter {
  final List<ArmyDot> army;
  final List<BurstHeart> burstHearts;
  final Offset target;

  ArmyAndHeartPainter(this.army, this.burstHearts, this.target);

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..style = PaintingStyle.fill;

    // رسم جزيئات الجيش الذهبية
    for (var dot in army) {
      paint.color = dot.color.withOpacity(0.6);
      canvas.drawCircle(Offset(dot.x, dot.y), 3.0, paint);
    }

    // رسم القلوب المتطايرة
    for (var heart in burstHearts) {
      paint.color = heart.color.withOpacity(heart.opacity);
      canvas.drawCircle(
        Offset(heart.x, heart.y),
        4.0 + (1.0 - heart.opacity) * 6,
        paint,
      );
    }

    // رسم دائرة الهدف المحيطة بالمؤشر
    paint.color = const Color(0xFFD4AF37).withOpacity(0.15);
    canvas.drawCircle(target, 45, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}
