```javascript name=server.js
require("dotenv").config();
const express = require("express");
const cors = require("cors");
const axios = require("axios");
const admin = require("firebase-admin");

const app = express();
const port = process.env.PORT || 8080;

// ===== Middlewares =====
app.use(cors());
app.use(express.json({ limit: "2mb" }));
app.use(express.urlencoded({ extended: true }));

// ===== Firebase Admin init =====
if (process.env.FIREBASE_PROJECT_ID) {
  admin.initializeApp({
    projectId: process.env.FIREBASE_PROJECT_ID,
  });
}

// ===== Helpers =====
async function writeToFirestoreLiveSession(payload) {
  if (!admin.apps.length) return { ok: false, message: "Firebase not initialized" };

  const db = admin.firestore();
  const ref = db.collection("aura_live_sessions").doc("lmkhizeni2");

  await ref.set(
    {
      ...payload,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    },
    { merge: true }
  );

  return { ok: true, message: "Firestore updated successfully" };
}

async function appendLiveChat(username, message) {
  if (!admin.apps.length) return { ok: false, message: "Firebase not initialized" };

  const db = admin.firestore();
  const chatRef = db
    .collection("aura_live_sessions")
    .doc("lmkhizeni2")
    .collection("live_chat");

  await chatRef.add({
    username,
    message,
    timestamp: admin.firestore.FieldValue.serverTimestamp(),
  });

  return { ok: true };
}

async function appendGift(payload) {
  if (!admin.apps.length) return { ok: false, message: "Firebase not initialized" };

  const db = admin.firestore();
  await db
    .collection("aura_live_sessions")
    .doc("lmkhizeni2")
    .collection("live_gifts")
    .add({
      ...payload,
      timestamp: admin.firestore.FieldValue.serverTimestamp(),
    });

  return { ok: true };
}

// ===== Routes =====

// Health endpoint required by Cloud Run
app.get("/health", (req, res) => {
  res.status(200).json({
    ok: true,
    status: "healthy",
    service: "aura-tiktok-bridge",
    time: new Date().toISOString(),
  });
});

// Root route
app.get("/", (req, res) => {
  res.status(200).json({
    service: "AURA TikTok Bridge",
    status: "running",
    docs: {
      health: "/health",
      liveSession: "POST /api/live-session",
      chat: "POST /api/live-chat",
      gift: "POST /api/live-gift",
      tikTokStatus: "GET /api/tiktok/status",
    },
  });
});

// Simulate a live session update coming from TikTok or admin panel
app.post("/api/live-session", async (req, res) => {
  try {
    const { currentViewers = 0, liveStatus = "live", title = "AURA ARMY" } = req.body;

    const result = await writeToFirestoreLiveSession({
      current_viewers: Number(currentViewers),
      live_status: liveStatus,
      title,
      source: "cloud-run",
    });

    return res.status(200).json({
      ok: true,
      ...result,
      currentViewers,
      liveStatus,
    });
  } catch (error) {
    console.error("live-session error:", error);
    return res.status(500).json({
      ok: false,
      message: "Failed to update live session",
      error: error.message,
    });
  }
});

// Add direct chat message
app.post("/api/live-chat", async (req, res) => {
  try {
    const { username = "guest", message = "" } = req.body;

    if (!message || !message.trim()) {
      return res.status(400).json({ ok: false, message: "Message is required" });
    }

    const result = await appendLiveChat(username, message);

    return res.status(200).json({
      ok: true,
      ...result,
      username,
      message,
    });
  } catch (error) {
    console.error("live-chat error:", error);
    return res.status(500).json({
      ok: false,
      message: "Failed to append chat",
      error: error.message,
    });
  }
});

// Add gift / like event
app.post("/api/live-gift", async (req, res) => {
  try {
    const { username = "guest", giftName = "like", amount = 1, from = "tiktok" } = req.body;

    const result = await appendGift({
      username,
      giftName,
      amount,
      from,
    });

    return res.status(200).json({
      ok: true,
      ...result,
      username,
      giftName,
      amount,
    });
  } catch (error) {
    console.error("live-gift error:", error);
    return res.status(500).json({
      ok: false,
      message: "Failed to append gift",
      error: error.message,
    });
  }
});

// TikTok status endpoint
app.get("/api/tiktok/status", async (req, res) => {
  try {
    const apiKey = process.env.TIKTOK_API_KEY;

    if (!apiKey) {
      return res.status(200).json({
        ok: true,
        connected: false,
        source: "stub",
        message: "TikTok API key not configured",
        live_status: "offline",
        currentViewers: 0,
      });
    }

    // Example direct TikTok SDK request adapter
    // In real use, replace with your official TikTok API call.
    const response = await axios.get("https://api.tiktok.com/...", {
      headers: {
        Authorization: `Bearer ${apiKey}`,
      },
      timeout: 10000,
    });

    return res.status(200).json({
      ok: true,
      connected: true,
      source: "tiktok",
      data: response.data,
    });
  } catch (error) {
    console.error("TikTok status error:", error.response?.data || error.message);

    return res.status(200).json({
      ok: true,
      connected: false,
      source: "stub",
      message: "TikTok API unavailable",
      live_status: "offline",
      currentViewers: 0,
    });
  }
});

// Optional Gemini bridge simulation
app.post("/api/gemini/command", async (req, res) => {
  try {
    const { prompt } = req.body;

    if (!process.env.GEMINI_API_KEY) {
      return res.status(200).json({
        ok: true,
        command: "mock",
        result: `Prompt received: ${prompt || "empty"}`,
        message: "Gemini key is not configured, returning mock result",
      });
    }

    // Here you can integrate Gemini API if needed.
    return res.status(200).json({
      ok: true,
      command: "gemini",
      result: `Gemini integration ready for prompt: ${prompt || ""}`,
    });
  } catch (error) {
    console.error("Gemini error:", error);
    return res.status(500).json({
      ok: false,
      message: "Gemini request failed",
      error: error.message,
    });
  }
});

// 404
app.use((req, res) => {
  res.status(404).json({
    ok: false,
    message: "Route not found",
    path: req.originalUrl,
  });
});

app.listen(port, () => {
  console.log(`AURA TikTok bridge running on port ${port}`);
});
